package com.finflow.legacy; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/legacy") class LegacyController{@GetMapping("/kyc/{customerId}")Map<String,Object>kyc(@PathVariable String customerId,@RequestParam(defaultValue="0")long delayMs,@RequestParam(defaultValue="false")boolean fail)throws Exception{Thread.sleep(delayMs);if(fail)throw new RuntimeException("Simulated SOAP mainframe failure");return Map.of("customerId",customerId,"kycStatus","VERIFIED","source","SOAP-SIMULATOR");}}